//! MCP wrappers for the rustre-symbols_v6 crate.
//! Extracted from `wire_tools.rs` by `workflow_split_wire_tools`.

use rustre_mcp_server::{McpError, ToolDefinition, ToolHandler, ToolResult};
use serde_json::{json, Value};
use async_trait::async_trait;

pub struct SymbolsV6SourcePriorityAllTool;
impl SymbolsV6SourcePriorityAllTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "symbols_v6_source_priority_all".to_string(), description: "Return SymbolSource::priority() for all variants.".to_string(), input_schema: json!({"type":"object"}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for SymbolsV6SourcePriorityAllTool { async fn call(&self, _args: Value) -> Result<ToolResult, McpError> { use rustre_symbols::SymbolSource as S; let all = [S::Pdb, S::Dwarf, S::CodeView, S::Stabs, S::Flirt, S::Manual, S::Inferred, S::Import, S::Export, S::Elf, S::Pe, S::Ai]; let v: Vec<(String, u8)> = all.iter().map(|s| (s.to_string(), s.priority())).collect(); Ok(ToolResult::text(json!({"priorities": v, "source":"rustre_symbols::SymbolSource::priority"}).to_string())) } }

pub struct SymbolsV6SynthNamesAllTool;
impl SymbolsV6SynthNamesAllTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "symbols_v6_synthetic_names_all".to_string(), description: "Generate function/data/label/dword/qword synthetic names for addr.".to_string(), input_schema: json!({"type":"object","properties":{"addr":{"type":"integer"}},"required":["addr"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for SymbolsV6SynthNamesAllTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let a = args.get("addr").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("missing 'addr'".into()))?; use rustre_symbols::SyntheticSymbolGen as G; Ok(ToolResult::text(json!({"function":G::function_name(a),"data":G::data_name(a),"label":G::label_name(a),"dword":G::dword_name(a),"qword":G::qword_name(a),"source":"rustre_symbols::SyntheticSymbolGen"}).to_string())) } }

pub struct SymbolsV6TryDemangleBatchTool;
impl SymbolsV6TryDemangleBatchTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "symbols_v6_try_demangle_batch".to_string(), description: "Apply rustre_symbols::try_demangle to a batch of names.".to_string(), input_schema: json!({"type":"object","properties":{"names":{"type":"array","items":{"type":"string"}}},"required":["names"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for SymbolsV6TryDemangleBatchTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let names = args.get("names").and_then(Value::as_array).ok_or_else(|| McpError::InvalidParams("missing 'names'".into()))?; let results: Vec<(String, Option<String>)> = names.iter().filter_map(|v| v.as_str().map(|s| (s.to_string(), rustre_symbols::try_demangle(s)))).collect(); let cnt = results.len(); Ok(ToolResult::text(json!({"results": results, "count": cnt, "source":"rustre_symbols::try_demangle"}).to_string())) } }

pub struct SymbolsV6FunctionBoundaryOpsTool;
impl SymbolsV6FunctionBoundaryOpsTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "symbols_v6_function_boundary_ops".to_string(), description: "FunctionBoundary::new/size/contains/overlaps.".to_string(), input_schema: json!({"type":"object","properties":{"start":{"type":"integer"},"end":{"type":"integer"},"probe":{"type":"integer"},"o_start":{"type":"integer"},"o_end":{"type":"integer"}},"required":["start","end","probe","o_start","o_end"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for SymbolsV6FunctionBoundaryOpsTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let s = args.get("start").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("start".into()))?; let e = args.get("end").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("end".into()))?; let p = args.get("probe").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("probe".into()))?; let os = args.get("o_start").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("o_start".into()))?; let oe = args.get("o_end").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("o_end".into()))?; let a = rustre_symbols::FunctionBoundary::new(s, e, "a".into()); let b = rustre_symbols::FunctionBoundary::new(os, oe, "b".into()); Ok(ToolResult::text(json!({"size_a":a.size(),"contains_probe":a.contains(p),"overlaps_ab":a.overlaps(&b),"display_a":a.to_string(),"source":"rustre_symbols::FunctionBoundary"}).to_string())) } }

pub struct SymbolsV6PdbUrlBuildTool;
impl SymbolsV6PdbUrlBuildTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "symbols_v6_pdb_url_build".to_string(), description: "Build PDB symbol server URL via PdbSymbolServer::pdb_url.".to_string(), input_schema: json!({"type":"object","properties":{"base":{"type":"string"},"pdb":{"type":"string"},"guid":{"type":"string"},"age":{"type":"integer"}},"required":["pdb","guid","age"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for SymbolsV6PdbUrlBuildTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let pdb = args.get("pdb").and_then(Value::as_str).ok_or_else(|| McpError::InvalidParams("pdb".into()))?; let guid = args.get("guid").and_then(Value::as_str).ok_or_else(|| McpError::InvalidParams("guid".into()))?; let age = args.get("age").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("age".into()))? as u32; let s = if let Some(b) = args.get("base").and_then(Value::as_str) { rustre_symbols::PdbSymbolServer::new(b) } else { rustre_symbols::PdbSymbolServer::msdl() }; let url = s.pdb_url(pdb, guid, age); Ok(ToolResult::text(json!({"url": url, "base": s.base_url, "source":"rustre_symbols::PdbSymbolServer::pdb_url"}).to_string())) } }

