pub struct SymbolsV6AddrMapLookupTool;
impl SymbolsV6AddrMapLookupTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "symbols_v6_addr_map_lookup".to_string(), description: "AddressToSymbolMap::from_symbols + lookup_exact + lookup_floor.".to_string(), input_schema: json!({"type":"object","properties":{"addrs":{"type":"array","items":{"type":"integer"}},"probe":{"type":"integer"}},"required":["addrs","probe"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for SymbolsV6AddrMapLookupTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let arr = args.get("addrs").and_then(Value::as_array).ok_or_else(|| McpError::InvalidParams("addrs".into()))?; let probe = args.get("probe").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("probe".into()))?; let syms: Vec<rustre_symbols::Symbol> = arr.iter().filter_map(|v| v.as_u64()).map(|a| rustre_symbols::Symbol::new(format!("f_{a:x}"), a, rustre_symbols::SymKind::Function)).collect(); let m = rustre_symbols::AddressToSymbolMap::from_symbols(&syms); let exact = m.lookup_exact(probe).map(|s| s.name.clone()); let floor = m.lookup_floor(probe).map(|s| s.name.clone()); Ok(ToolResult::text(json!({"len":m.len(),"exact":exact,"floor":floor,"source":"rustre_symbols::AddressToSymbolMap"}).to_string())) } }

pub struct SymbolsV6ConflictResolveTool;
impl SymbolsV6ConflictResolveTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "symbols_v6_conflict_resolve".to_string(), description: "Resolve conflicting symbols via SymbolConflictResolver::KeepFirst.".to_string(), input_schema: json!({"type":"object","properties":{"names":{"type":"array","items":{"type":"string"}},"addr":{"type":"integer"}},"required":["names","addr"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for SymbolsV6ConflictResolveTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let names = args.get("names").and_then(Value::as_array).ok_or_else(|| McpError::InvalidParams("names".into()))?; let addr = args.get("addr").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("addr".into()))?; let syms: Vec<rustre_symbols::Symbol> = names.iter().filter_map(|v| v.as_str()).map(|n| rustre_symbols::Symbol::new(n.to_string(), addr, rustre_symbols::SymKind::Function)).collect(); let r = rustre_symbols::SymbolConflictResolver::new(rustre_symbols::ConflictStrategy::KeepFirst).resolve(syms); let out_names: Vec<String> = r.iter().map(|s| s.name.clone()).collect(); let cnt = r.len(); Ok(ToolResult::text(json!({"kept": out_names, "count": cnt, "source":"rustre_symbols::SymbolConflictResolver"}).to_string())) } }

pub struct SymbolsV6UnifiedTableOpsTool;
impl SymbolsV6UnifiedTableOpsTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "symbols_v6_unified_table_ops".to_string(), description: "UnifiedSymbolTable add/lookup_name/nearest_below/len.".to_string(), input_schema: json!({"type":"object","properties":{"entries":{"type":"array","items":{"type":"object"}},"probe":{"type":"integer"},"name_q":{"type":"string"}},"required":["entries","probe"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for SymbolsV6UnifiedTableOpsTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let entries = args.get("entries").and_then(Value::as_array).ok_or_else(|| McpError::InvalidParams("entries".into()))?; let probe = args.get("probe").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("probe".into()))?; let mut t = rustre_symbols::UnifiedSymbolTable::new(); for e in entries { let name = e.get("name").and_then(Value::as_str).unwrap_or("s").to_string(); let addr = e.get("addr").and_then(Value::as_u64).unwrap_or(0); t.add(rustre_symbols::UnifiedSymbol::new(name, addr, rustre_symbols::SymbolKind::Function, rustre_symbols::SymbolSource::Manual)); } let nb = t.nearest_below(probe).map(|s| s.name.clone()); let name_q = args.get("name_q").and_then(Value::as_str).unwrap_or(""); let by_name = t.lookup_name(name_q).len(); Ok(ToolResult::text(json!({"len":t.len(),"nearest_below":nb,"by_name_count":by_name,"source":"rustre_symbols::UnifiedSymbolTable"}).to_string())) } }

pub struct SymbolsV6DemangleAllTableTool;
impl SymbolsV6DemangleAllTableTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "symbols_v6_demangle_all_table".to_string(), description: "Apply demangle_all to a UnifiedSymbolTable built from names.".to_string(), input_schema: json!({"type":"object","properties":{"names":{"type":"array","items":{"type":"string"}}},"required":["names"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for SymbolsV6DemangleAllTableTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let names = args.get("names").and_then(Value::as_array).ok_or_else(|| McpError::InvalidParams("missing 'names'".into()))?; let mut t = rustre_symbols::UnifiedSymbolTable::new(); for (i, v) in names.iter().enumerate() { if let Some(n) = v.as_str() { t.add(rustre_symbols::UnifiedSymbol::new(n.to_string(), (i as u64) * 0x10 + 0x1000, rustre_symbols::SymbolKind::Function, rustre_symbols::SymbolSource::Elf)); } } rustre_symbols::demangle_all(&mut t); let demangled: Vec<(String, Option<String>)> = t.iter_by_address().map(|s| (s.name.clone(), s.demangled_name.clone())).collect(); let ln = t.len(); Ok(ToolResult::text(json!({"results": demangled, "len": ln, "source":"rustre_symbols::demangle_all"}).to_string())) } }

